@MainActor
@Observable
final class GalleryViewModel {
    var thumbnails: [UIImage] = []
    private var loadTask: Task<Void, Never>?

    func load(_ urls: [URL]) {
        loadTask?.cancel()
        loadTask = Task {                       // inherits @MainActor
            let images = await Thumbnailer.make(urls)   // runs off main
            guard !Task.isCancelled else { return }
            thumbnails = images                 // back on main
        }
    }
    func stop() { loadTask?.cancel() }
}

enum Thumbnailer {
    @concurrent
    static func make(_ urls: [URL]) async -> [UIImage] { /* CPU heavy */ [] }
}
